import { addDays } from '../claims/overdue';

// Due is worked in exact integers: an amount in cents times a rate in hundredths of a percent is
// due in millionths, then rounded half to even to cents. No float ever touches it.

export const NA = 'n/a';

/** "10.25" -> 1025n. */
export function toCents(amount: string): bigint {
  const negative = amount.trim().startsWith('-');
  const [whole, frac = ''] = amount.trim().replace(/^[-+]/, '').split('.');
  const cents = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
  return negative ? -cents : cents;
}

/** 1025n -> "10.25". */
export function formatCents(cents: bigint): string {
  const negative = cents < 0n;
  const abs = negative ? -cents : cents;
  const frac = (abs % 100n).toString().padStart(2, '0');
  return `${negative ? '-' : ''}${abs / 100n}.${frac}`;
}

/** The due on an amount of cents at a rate ("12.50"), in cents; null when there is no rate. */
export function dueCents(cents: bigint, rate: string | undefined): bigint | null {
  if (rate === undefined) return null;
  const millionths = cents * toCents(rate);
  const negative = millionths < 0n;
  const abs = negative ? -millionths : millionths;
  const whole = abs / 10000n;
  const rest = abs % 10000n;
  const rounded = rest > 5000n || (rest === 5000n && whole % 2n === 1n) ? whole + 1n : whole;
  return negative ? -rounded : rounded;
}

/** A due for display: two decimals, or n/a. */
export function showDue(due: bigint | null): string {
  return due === null ? NA : formatCents(due);
}

/** A live due raised to the sheet's floor ("1.00"); n/a stays n/a. */
export function floored(due: bigint | null, floor: string): bigint | null {
  if (due === null) return null;
  const min = toCents(floor);
  return due < min ? min : due;
}

/** What a late charge needs: the sheet's late percent ("10.00"), its terms in days and its today. */
export type Late = { pct: string; terms: number; today: string | undefined };

const DAY_MS = 86_400_000;

/** The late charge on a figure in cents: an OPEN claim whose due-by (its date plus the terms) is
 *  before today gains the late percent of its figure for every full 30 days it is overdue, rounded
 *  like due. Never bound by a statement; settling freezes it into the settled due. */
export function lateCents(claim: { date: string; status?: string }, figure: bigint, late: Late | undefined): bigint {
  if (late === undefined || late.today === undefined || claim.status !== 'OPEN') return 0n;
  const dueBy = addDays(claim.date, late.terms);
  const days = Math.round((Date.parse(late.today) - Date.parse(dueBy)) / DAY_MS);
  const periods = days > 0 ? Math.floor(days / 30) : 0;
  return dueCents(figure * BigInt(periods), late.pct) ?? 0n;
}

/** A claim's due: the one fixed when it was settled or bound by a statement (a claim bound to n/a
 *  stays n/a), else its amount at the current rate, raised to the sheet's floor; an overdue claim's
 *  late charge is added on top. */
export function claimDue(
  claim: { amount: string; due: string; date: string; status?: string; stated?: boolean },
  rate: string | undefined,
  floor: string,
  late?: Late,
): bigint | null {
  const figure = claim.due !== '' ? toCents(claim.due) : claim.stated ? null : floored(dueCents(toCents(claim.amount), rate), floor);
  return figure === null ? null : figure + lateCents(claim, figure, late);
}

/** A person's due-total: the sum of the figures of their claims that count. With no rate for their
 *  grade today it is n/a, unless a claim keeps a figure (a settled one, or one worked at the grade
 *  in force on its date); then it is the sum of the figures there are. A claim whose figure is n/a
 *  adds nothing. */
export function dueTotal(
  claims: { amount: string; due: string; date: string; status?: string; stated?: boolean }[],
  rateOn: (date: string) => string | undefined,
  rateToday: string | undefined,
  floor: string,
  late?: Late,
): bigint | null {
  const figures = claims.map((c) => claimDue(c, rateOn(c.date), floor, late));
  if (rateToday === undefined && figures.every((f) => f === null)) return null;
  return figures.reduce<bigint>((sum, f) => sum + (f ?? 0n), 0n);
}
import type { Claim } from './useClaims';

/** A date ("2026-03-01") moved on by a number of days, as YYYY-MM-DD. Worked in UTC so no time
 *  zone shifts it. */
export function addDays(date: string, days: number): string {
  const [y, m, d] = date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + days)).toISOString().slice(0, 10);
}

/** A claim's due-by: its date plus the sheet's terms. */
export const dueBy = (c: Claim, terms: number) => addDays(c.date, terms);

/** A claim is overdue when it is OPEN and its due-by is before the sheet's today. */
export const isOverdue = (c: Claim, terms: number, today: string | undefined) =>
  c.status === 'OPEN' && today !== undefined && dueBy(c, terms) < today;
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/** A claim; `amount` is shown with two decimals ("10.25"); `number` is the one given when it was
 *  opened (a voided claim keeps it), "" for a draft; `due` is the due fixed when it was settled, else the
 *  figure the person's last statement bound it to, "" while its due is live (worked from the current
 *  rate) or bound to n/a; `stated` is whether the last statement bound it. */
export type Claim = {
  id: string;
  personId: string;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string;
  due: string;
  /** The user who opened the claim, "" if it was never opened. */
  openedBy: string;
  stated: boolean;
};

/** Only OPEN and SETTLED claims count toward claimed, due-total and every total. */
export const counts = (c: Claim) => c.status === 'OPEN' || c.status === 'SETTLED';

/** Whether a claim counts in the live totals: it counts, and is not OPEN while its person is held. */
export const countsLive = (c: Claim, held: boolean) => counts(c) && !(held && c.status === 'OPEN');

export const claimsKey = (sheet: string) => ['sheet', sheet, 'claims'] as const;

/** The sheet's claims, newest first. */
export function useClaims(sheet: string): Claim[] {
  const { data } = useQuery({
    queryKey: claimsKey(sheet),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheet)}/claims`),
    enabled: sheet !== '',
  });
  return data ?? [];
}

/** The amounts of the claims that count added up, shown with two decimals. Summed in whole cents
 *  so no float drift shows. */
export function sumAmounts(claims: Claim[]): string {
  const cents = claims.filter(counts).reduce((sum, c) => sum + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
import { useEffect, useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { claimsKey, type Claim } from './useClaims';

// The claim form on a person's row: adds a claim to that person, or — while one of their claims'
// editor is open (`editClaim` in the URL) — saves that claim. Opening the editor fills the form
// with the claim's values. A blank date takes the sheet's today.
export function ClaimForm({ personId, claims }: { personId: string; claims: Claim[] }) {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const [editParam, setEditing] = useSearchParam('editClaim', asString);
  const edited = claims.find((c) => c.id === editParam);
  // A claim not under this person has no editor open here.
  const editing = edited?.id ?? '';
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState('');
  const [note, setNote] = useState('');
  const queryClient = useQueryClient();
  const submitOnce = useSubmitOnce();

  const clear = () => {
    setAmount('');
    setDate('');
    setNote('');
  };

  const save = useMutation({
    mutationFn: (body: { amount: string; date: string; note: string }) =>
      editing !== ''
        ? putJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${encodeURIComponent(editing)}`, { ...body, user })
        : postJson<Claim>(
            `/api/sheets/${encodeURIComponent(sheet)}/people/${encodeURIComponent(personId)}/claims`,
            { ...body, user },
          ),
    onSuccess: () => {
      clear();
      if (editing !== '') setEditing(undefined);
      void queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
  });

  // Opening (or closing) an editor fills the form with that claim's values (or empties it).
  const editedId = edited?.id;
  useEffect(() => {
    save.reset();
    if (edited) {
      setAmount(edited.amount);
